import { useRef, type KeyboardEvent } from "react";
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  id: string;
  name: string;
  time: string;
  state: TimeState;
}

export interface TimeListProps {
  items: readonly TimeItem[];
  label?: string;
}

export function TimeList({ items, label = "Daily times" }: TimeListProps) {
  const rowRefs = useRef<(HTMLLIElement | null)[]>([]);

  function focusRow(index: number): void {
    rowRefs.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLLIElement>, index: number): void {
    const last = items.length - 1;
    let target: number;

    switch (event.key) {
      case "ArrowDown":
      case "ArrowRight":
        target = Math.min(index + 1, last);
        break;
      case "ArrowUp":
      case "ArrowLeft":
        target = Math.max(index - 1, 0);
        break;
      case "Home":
        target = 0;
        break;
      case "End":
        target = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    focusRow(target);
  }

  return (
    <ul className="time-list" aria-label={label}>
      {items.map((item, index) => {
        const isNext = item.state === "next";

        return (
          <li
            key={item.id}
            ref={(el) => {
              rowRefs.current[index] = el;
            }}
            className={`time-list__item time-list__item--${item.state}`}
            tabIndex={0}
            aria-current={isNext ? "time" : undefined}
            data-state={item.state}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="time-list__name">
              {item.name}
              {isNext && <span className="time-list__badge">Next</span>}
            </span>
            <span className="time-list__time">{item.time}</span>
          </li>
        );
      })}
    </ul>
  );
}
